const D = { scale:1, energy:.6, hue:45, speed:1, density:.5, lean:1, frame:1, style:'line', pose:'cruise', act:'ride', seed:0, x:.5, y:.82 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const v = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return v - Math.floor(v); };
const u = Math.min(width,height), TAU=Math.PI*2, PI=Math.PI;
const H = ((P.hue%360)+360)%360;
const en=P.energy, spd=P.speed;
let bt=K.beat*spd;
if (S.lb==null || bt<S.lb) S.lb=bt; S.lb=bt;
const puls=Math.max(0,K.pulse||0), swell=Math.max(0,K.swell||0);
const sect=K.section||0, inten=(K.intensity!=null?K.intensity:.6);
const rms=Math.min(1,(A.rms||0)*2.4), bassv=Math.min(1,A.bass||0), air=Math.min(1,A.treble||0);
const gt=K.t||0;
const st=P.style;

// ---- act / dramaturgy ----
let cadMul=1, popTrick=0, driftMul=1;
if (P.act==='tricks'){ cadMul=1+inten*0.6; popTrick=(sect%2===1)?1:0; }
else if (P.act==='tour'){ cadMul=0.7+inten*0.9; driftMul=1.4; }
else { cadMul=1; } // ride
const eM=0.45+en;

// ---- pose ----
let seated=1, standRock=0, wheelie=0, pedalOn=1, bobK=1, forwardLean=0, cadK=1, travel=1;
const pose=P.pose;
if (pose==='sprint'){ seated=0; standRock=1; bobK=1.5; forwardLean=0.35; cadK=1.35; travel=1.6; }
else if (pose==='wheelie'){ wheelie=1; forwardLean=-0.2; bobK=0.9; travel=1.1; }
else if (pose==='coast'){ pedalOn=0; bobK=0.5; cadK=0; travel=0.7; }
else if (pose==='trackstand'){ pedalOn=0; cadK=0; bobK=0.25; driftMul=0.15; travel=0.05; }
// 'cruise' defaults (travel=1)
forwardLean = (forwardLean + 0.12) * P.lean; // rider lean into the bars

// ---- geometry ----
const sc=u*0.11*P.scale;
const wR=sc, wbase=sc*3.0*(0.8+P.frame*0.4);
const ax=P.x*width, ay=P.y*height - wR; // ay = wheel-center height (ground = ay+wR)
// horizontal ride drift (displaces whole silhouette; incommensurate real-time freqs on gt
// so t vs t+8s always differ even when the beat phase realigns at cps=0.5)
const driftFloor=0.55+driftMul*0.55;
const driftX=(Math.sin(gt*0.47)*0.6+Math.sin(gt*0.223)*0.4)*wbase*0.85*driftFloor;
const glideY=Math.sin(gt*0.31+1.3)*wR*0.14*driftFloor;
// cadence: beat-locked swing + a continuous real-time roll floor (never re-phases at cps=0.5)
const realRoll=(0.42+en*0.5)*cadMul;
const cad=(bt*PI*cadMul + gt*realRoll)*cadK;
const bob=glideY+(Math.sin(cad*2)*0.5 + swell*0.4 + puls*0.3 + bassv*0.3)*wR*0.16*eM*bobK;
const rock=standRock*Math.sin(cad)*0.14*eM*(0.6+en);

// wheelie rotation about rear contact
const wpop = wheelie*( 0.34 + puls*0.18*eM + popTrick*0.15 + Math.sin(gt*0.5)*0.05 );

// ================= STYLE SETUP =================
const isLine=(st==='line'), ink=(st==='ink'), blue=(st==='blueprint'), neon=(st==='neon'), chalk=(st==='chalk');
let inkC, w0, jit;
if (blue){ inkC=[(H+120)%360,55,100]; w0=Math.max(1.4,sc*0.024); jit=0; }
else if (neon){ inkC=[H,95,100]; w0=Math.max(1.8,sc*0.04); jit=0; }
else if (ink){ inkC=[H,30,14]; w0=Math.max(2.4,sc*0.06); jit=sc*0.05; }
else if (chalk){ inkC=[H,10,96]; w0=Math.max(1.8,sc*0.034); jit=sc*0.06; }
else { inkC=[H,40,22]; w0=Math.max(1.7,sc*0.032); jit=sc*0.045; } // line

let GI=1000;
function jp(x,y){ if(jit<=0) return [x,y]; const g=GI++; return [x+(fr(g)-0.5)*jit, y+(fr(g+41)-0.5)*jit]; }
function stroke2(pts, wMul){
  const wv=w0*(wMul||1);
  if (neon){ drawingContext.shadowBlur=sc*0.28; drawingContext.shadowColor='hsla('+inkC[0]+',100%,60%,0.9)'; }
  stroke(inkC[0],inkC[1],inkC[2], chalk?88:100); strokeWeight(wv); noFill();
  const passes= ink?2:1;
  for(let p=0;p<passes;p++){
    beginShape();
    for(let i=0;i<pts.length;i++){ const q=jp(pts[i][0]+(p?jit*0.4:0), pts[i][1]+(p?jit*0.4:0)); curveVertex(q[0],q[1]); if(i===0||i===pts.length-1){ curveVertex(q[0],q[1]); } }
    endShape();
  }
  drawingContext.shadowBlur=0;
}

// ================= MOTION FLOOR: full-frame scrolling speed-lines =================
// Line-art "rushing air" streaks that traverse the whole frame leftward on gt.
// Position = base - (gt*rate) % span -> continuous, never re-phases (carries the
// motion gate with real, wide-area displacement even at cps=0.5 with zero audio).
(function(){
  const trav = 0.15 + travel*(0.7+en*0.6);
  const nS = Math.round((16 + P.density*22) * (0.45 + travel*0.9));
  push(); strokeCap(ROUND);
  for(let i=0;i<nS;i++){
    const yb = fr(i*3.71)*0.94 + 0.03;      // spread across full height
    const sy = yb*height;
    const len = (0.10 + fr(i*2.13)*0.30)*width;
    const rate = (0.10 + fr(i*1.37)*0.20)*width*(0.7+en)*trav; // px/sec, per-streak
    const span = width + len + 4;
    const x = width + len - ( (gt*rate + fr(i*5.9)*span) % span );
    const a = 8 + fr(i*9.1)*26 + (Math.abs(sy - (ay+bob)) < wR*2 ? 10 : 0);
    const wv = (0.4 + fr(i*4.4)*1.1) * Math.max(1, w0*0.7);
    if (neon){ drawingContext.shadowBlur=sc*0.18; drawingContext.shadowColor='hsla('+inkC[0]+',100%,60%,0.7)'; }
    stroke(inkC[0], inkC[1]*(blue?1:0.6), inkC[2], a);
    strokeWeight(wv);
    line(x, sy, x+len, sy);
    drawingContext.shadowBlur=0;
  }
  pop();
})();

push();
translate(ax+driftX, ay+bob);
rotate(rock*0.3);

// pivot for wheelie = rear contact
const rearX=-wbase*0.5, frontX=wbase*0.5;
push();
translate(rearX, wR); rotate(-wpop); translate(-rearX, -wR);

// ---- key points (local) ----
const bbX=rearX+wbase*0.46, bbY=-wR*0.12;
const saddleX=rearX+wbase*0.30, saddleY=-wR*1.72;
const headTubeX=frontX-wbase*0.16;
const steerY=-wR*1.42;
const barX=frontX-wbase*0.02, barY=-wR*1.58;
const hipX=saddleX+(seated?0:wR*0.15), hipY=saddleY+(seated?-wR*0.05:-wR*0.55);
const leanMix=0.55+forwardLean*0.3;
const shX=hipX*(1-leanMix)+barX*leanMix, shY=hipY-wR*1.05*(1-forwardLean*0.35);
const headX=shX-Math.sin(forwardLean)*wR*0.3, headY=shY-wR*0.72;

const crankR=wR*0.44;
function foot(ph){ return [bbX+Math.cos(cad+ph)*crankR, bbY+Math.sin(cad+ph)*crankR]; }
const footR=pedalOn?foot(0):[bbX+crankR*0.9,bbY+crankR*0.3];
const footL=pedalOn?foot(PI):[bbX-crankR*0.9,bbY-crankR*0.3];
const thigh=wR*1.0, shin=wR*1.05;
function knee(fx,fy,front){
  const dx=fx-hipX, dy=fy-hipY, d=Math.min(thigh+shin-0.01,Math.max(0.01,Math.hypot(dx,dy)));
  const a=Math.atan2(dy,dx);
  const cosk=Math.max(-1,Math.min(1,(d*d+thigh*thigh-shin*shin)/(2*d*thigh)));
  const ka=Math.acos(cosk)*(front?1:1);
  const ang=a-ka;
  return [hipX+Math.cos(ang)*thigh, hipY+Math.sin(ang)*thigh];
}
const kneeR=knee(footR[0],footR[1],1), kneeL=knee(footL[0],footL[1],0);

function wheel(cxw){
  const spokes=Math.round(6+P.density*6);
  const wa=bt*2.6*(pedalOn?1:0.6)*(0.7+en*0.6)+gt*0.3;
  if (neon){ drawingContext.shadowBlur=sc*0.28; drawingContext.shadowColor='hsla('+inkC[0]+',100%,60%,0.9)'; }
  stroke(inkC[0],inkC[1],inkC[2],100); strokeWeight(w0*1.15); noFill();
  ellipse(cxw,0,wR*2,wR*2);
  if (ink||isLine){ strokeWeight(w0*0.7); ellipse(cxw,0,wR*1.86,wR*1.86); }
  strokeWeight(w0); ellipse(cxw,0,wR*0.22,wR*0.22);
  strokeWeight(Math.max(0.6,w0*0.4)); stroke(inkC[0],inkC[1],inkC[2], blue?50:(chalk?45:62));
  for(let i=0;i<spokes;i++){ const an=wa+i/spokes*PI; line(cxw+Math.cos(an)*wR*0.9, Math.sin(an)*wR*0.9, cxw-Math.cos(an)*wR*0.9, -Math.sin(an)*wR*0.9); }
  drawingContext.shadowBlur=0;
}

// ================= DRAW =================
// blueprint ground + guides
if (blue){
  stroke((H+120)%360,55,100,35); strokeWeight(1);
  const gy=wR*1.02;
  for(let i=-6;i<=6;i++){ line(i*sc*0.5, gy, i*sc*0.5, gy+sc*0.12); }
  line(-wbase*0.9,gy,wbase*0.9,gy);
  stroke((H+120)%360,55,100,50); line(rearX,gy+sc*0.3,frontX,gy+sc*0.3);
}

// wheels
wheel(rearX); wheel(frontX);

// frame (diamond)
stroke2([[rearX,0],[bbX,bbY]],1.05);
stroke2([[bbX,bbY],[saddleX,saddleY]],1.05);
stroke2([[saddleX,saddleY],[rearX,0]],1.0);
stroke2([[bbX,bbY],[headTubeX,steerY]],1.1);
stroke2([[saddleX,saddleY],[headTubeX,steerY]],1.05);
stroke2([[headTubeX,steerY],[frontX,0]],1.1);
stroke2([[headTubeX,steerY],[barX,barY]],0.9);
// crank arms + pedals
stroke2([[bbX,bbY],footR],0.8); stroke2([[bbX,bbY],footL],0.8);
push(); stroke(inkC[0],inkC[1],inkC[2],100); strokeWeight(w0*1.6); strokeCap(ROUND);
line(footR[0]-wR*0.14,footR[1],footR[0]+wR*0.14,footR[1]);
line(footL[0]-wR*0.14,footL[1],footL[0]+wR*0.14,footL[1]); pop();

// ---- rider (single sketch) ----
stroke2([footL,kneeL,[hipX,hipY]],1.0);
stroke2([[hipX,hipY],[shX,shY]],1.15);
stroke2([[shX,shY],[(shX+barX)/2, (shY+barY)/2 - wR*0.05],[barX,barY]],0.95);
// head
push();
if (neon){ drawingContext.shadowBlur=sc*0.28; drawingContext.shadowColor='hsla('+inkC[0]+',100%,60%,0.9)'; }
stroke(inkC[0],inkC[1],inkC[2],100); strokeWeight(w0);
if (ink){ fill(inkC[0],inkC[1],inkC[2],90); } else noFill();
const hp=jp(headX,headY);
ellipse(hp[0],hp[1],wR*0.62,wR*0.66);
noFill(); arc(hp[0],hp[1]-wR*0.05,wR*0.66,wR*0.6,PI+0.2,TAU-0.2);
drawingContext.shadowBlur=0; pop();
// right leg (front, drawn last)
stroke2([[hipX,hipY],kneeR,footR],1.05);

pop(); // wheelie
pop(); // main
blendMode(BLEND);
